grant insert on table "public"."processed_messages" to "authenticated";

grant references on table "public"."processed_messages" to "authenticated";

grant select on table "public"."processed_messages" to "authenticated";

grant trigger on table "public"."processed_messages" to "authenticated";

grant truncate on table "public"."processed_messages" to "authenticated";

grant update on table "public"."processed_messages" to "authenticated";

grant delete on table "public"."processed_messages" to "postgres";

grant insert on table "public"."processed_messages" to "postgres";

grant references on table "public"."processed_messages" to "postgres";

