grant insert on table "public"."processed_messages" to "service_role";

grant references on table "public"."processed_messages" to "service_role";

grant select on table "public"."processed_messages" to "service_role";

grant trigger on table "public"."processed_messages" to "service_role";

grant truncate on table "public"."processed_messages" to "service_role";

grant update on table "public"."processed_messages" to "service_role";


  create policy "Enable insert for authenticated users only"
  on "public"."processed_messages"
  as permissive
  for insert
  to authenticated
with check (true);

-- Create the queue
select pgmq.create('testq');

-- Enable RLS on queue table
alter table pgmq.q_testq enable row level security;

-- Create policy for authenticated users
create policy "Enable all operations for authenticated users"
on pgmq.q_testq
as permissive
for all
to authenticated
using (true)
with check (true);

-- Grant permissions to authenticated role
grant select, insert, update, delete on table pgmq.q_testq to authenticated;

grant usage on schema pgmq to anon, authenticated, service_role;
grant execute on all functions in schema pgmq to anon, authenticated, service_role;

grant select, insert, update, delete on table pgmq.q_testq to service_role;


